using namespace std;

long long gcdOf(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    int cn = (int)n;
    vector<vector<long long>> table;
    table.push_back(a);
    for (int j = 1; (1 << j) <= cn; j++) {
        int half = 1 << (j - 1);
        vector<long long> row(cn - (1 << j) + 1);
        for (int i = 0; i < (int)row.size(); i++) row[i] = gcdOf(table[j - 1][i], table[j - 1][i + half]);
        table.push_back(row);
    }
    string out;
    for (long long t = 0; t < q; t++) {
        int l = (int)qs[t][0], rr = (int)qs[t][1];
        int k = 31 - __builtin_clz(rr - l + 1);
        if (t) out += " ";
        out += to_string(gcdOf(table[k][l - 1], table[k][rr - (1 << k)]));
    }
    cout << out << "\n";

    return 0;
}

