import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long gcdOf(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        int levels = 1;
        while ((1 << levels) <= cn) levels++;
        long[][] table = new long[levels][];
        table[0] = a.clone();
        for (int j = 1; j < levels; j++) {
            int half = 1 << (j - 1);
            table[j] = new long[cn - (1 << j) + 1];
            for (int i = 0; i < table[j].length; i++) table[j][i] = gcdOf(table[j - 1][i], table[j - 1][i + half]);
        }
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            int l = (int) qs[t][0], rr = (int) qs[t][1];
            int k = 31 - Integer.numberOfLeadingZeros(rr - l + 1);
            if (t > 0) out.append(" ");
            out.append(gcdOf(table[k][l - 1], table[k][rr - (1 << k)]));
        }
        System.out.println(out);
    }
}
